(N'Chậu sứ Bát Tràng cao cấp cắm 5 cành lan hồ điệp tím viền trắng cánh dày, hoa bền tươi trên 1 tháng.'),
(N'Lọ Hoa Để Bàn Hoa Hồng Nhung Đỏ'),
(N'Bình thủy tinh cắm hoa hồng nhung đỏ và hoa limonium tím nhỏ xinh, trang trí bàn làm việc sang trọng.'),
(N'Chậu Hoa Văn Phòng Bình An Xanh Mướt'),
(N'Chậu hoa tươi hỗn hợp xanh mướt trang trí văn phòng, hành lang, mang lại không khí trong lành và thanh thản.'),
(N'Giảm 20K cho đơn từ 200K'),
(N'Giảm 10% tri ân khách hàng'),
(N'Miễn phí vận chuyển toàn quốc'),
(N'Gia Hân Khách Hàng'),
(N'123 Lê Lợi, P. Bến Nghé, Quận 1, TP.HCM'),
(N'Hoa hồng đỏ Ecuador nhận được rất tươi, cánh hoa nở to đều và thơm dịu. Đóng gói cẩn thận có thiệp viết tay rất chỉn chu. Shipper giao hoa đúng giờ hẹn, phục vụ rất nhiệt tình!'),
(N'UPDATE dbo.orders SET shipping_method = ''PICKUP'' WHERE recipient_address LIKE N''Nhận tại chi nhánh:%'' AND shipping_method = ''DELIVERY'''),
(N'UPDATE t SET order_id = o.id FROM dbo.transactions t JOIN dbo.orders o ON t.description LIKE N''Thu nhập đơn hàng #'' + CAST(o.id AS NVARCHAR(20)) + N'' sau%'' WHERE t.order_id IS NULL AND t.type = ''ORDER_PAYMENT'''),
(N'UPDATE dbo.products SET price_buy = 750000.00 WHERE (price_buy IS NULL OR price_buy = 0) AND name LIKE N''%Cẩm Tú Cầu%'''),
(N'UPDATE dbo.products SET sold = 24 WHERE sold IS NULL AND name LIKE N''%Cẩm Tú Cầu%'''),
(N'UPDATE p SET p.category_id = (SELECT TOP 1 c.id FROM dbo.categories c WHERE c.name LIKE N''%Sinh Nhật%'' OR c.name LIKE N''%Hoa%'') FROM dbo.products p WHERE p.category_id IS NULL'),
(N'Bó hoa hồng đỏ Ecuador, hoa baby trắng lãng mạn tỏ tình'),
(N'IF NOT EXISTS (SELECT 1 FROM dbo.categories WHERE name = N''Bó Hoa Sinh Nhật'') INSERT INTO dbo.categories (name, description, parent_id) SELECT N''Bó Hoa Sinh Nhật'', N''Các mẫu bó hoa tươi rực rỡ chúc mừng sinh nhật'', id FROM dbo.categories WHERE name = N''Hoa Sinh Nhật'''),
(N'IF NOT EXISTS (SELECT 1 FROM dbo.categories WHERE name = N''Lẵng Hoa Sinh Nhật'') INSERT INTO dbo.categories (name, description, parent_id) SELECT N''Lẵng Hoa Sinh Nhật'', N''Lẵng hoa để bàn chúc mừng sinh nhật sang trọng'', id FROM dbo.categories WHERE name = N''Hoa Sinh Nhật'''),
(N'IF NOT EXISTS (SELECT 1 FROM dbo.categories WHERE name = N''Bó Hoa Hồng Đỏ'') INSERT INTO dbo.categories (name, description, parent_id) SELECT N''Bó Hoa Hồng Đỏ'', N''Bó hoa hồng đỏ nhập khẩu quyến rũ trao gửi tình yêu'', id FROM dbo.categories WHERE name = N''Hoa Tình Yêu & Valentine'''),
(N'IF NOT EXISTS (SELECT 1 FROM dbo.categories WHERE name = N''Bó Hoa Baby Trắng'') INSERT INTO dbo.categories (name, description, parent_id) SELECT N''Bó Hoa Baby Trắng'', N''Bó hoa baby trắng tinh khôi, nhẹ nhàng lãng mạn'', id FROM dbo.categories WHERE name = N''Hoa Tình Yêu & Valentine'''),
(N'IF NOT EXISTS (SELECT 1 FROM dbo.categories WHERE name = N''Kệ Hoa Khai Trương'') INSERT INTO dbo.categories (name, description, parent_id) SELECT N''Kệ Hoa Khai Trương'', N''Kệ hoa chúc mừng khai trương hồng phát sang trọng'', id FROM dbo.categories WHERE name = N''Hoa Khai Trương'''),
(N'IF NOT EXISTS (SELECT 1 FROM dbo.categories WHERE name = N''Lẵng Hoa Khai Trương Để Bàn'') INSERT INTO dbo.categories (name, description, parent_id) SELECT N''Lẵng Hoa Khai Trương Để Bàn'', N''Lẵng hoa để bàn quầy lễ tân khai trương'', id FROM dbo.categories WHERE name = N''Hoa Khai Trương'''),
(N'IF NOT EXISTS (SELECT 1 FROM dbo.categories WHERE name = N''Chậu Lan Hồ Điệp Trắng'') INSERT INTO dbo.categories (name, description, parent_id) SELECT N''Chậu Lan Hồ Điệp Trắng'', N''Chậu lan hồ điệp trắng đại diện cho sự thanh cao, sang trọng'', id FROM dbo.categories WHERE name = N''Lan Hồ Điệp Sang Trọng'''),
(N'IF NOT EXISTS (SELECT 1 FROM dbo.categories WHERE name = N''Chậu Lan Hồ Điệp Vàng'') INSERT INTO dbo.categories (name, description, parent_id) SELECT N''Chậu Lan Hồ Điệp Vàng'', N''Lan hồ điệp vàng mang lại tài lộc và phú quý'', id FROM dbo.categories WHERE name = N''Lan Hồ Điệp Sang Trọng'''),
(N'UPDATE c SET c.parent_id = p.id FROM dbo.categories c, dbo.categories p WHERE c.name IN (N''Bó Hoa Sinh Nhật'', N''Lẵng Hoa Sinh Nhật'') AND p.name = N''Hoa Sinh Nhật'' AND (c.parent_id IS NULL OR c.parent_id <> p.id)'),
(N'UPDATE c SET c.parent_id = p.id FROM dbo.categories c, dbo.categories p WHERE c.name IN (N''Bó Hoa Hồng Đỏ'', N''Bó Hoa Baby Trắng'') AND p.name = N''Hoa Tình Yêu & Valentine'' AND (c.parent_id IS NULL OR c.parent_id <> p.id)'),
(N'UPDATE c SET c.parent_id = p.id FROM dbo.categories c, dbo.categories p WHERE c.name IN (N''Kệ Hoa Khai Trương'', N''Lẵng Hoa Khai Trương Để Bàn'') AND p.name = N''Hoa Khai Trương'' AND (c.parent_id IS NULL OR c.parent_id <> p.id)'),
(N'UPDATE c SET c.parent_id = p.id FROM dbo.categories c, dbo.categories p WHERE c.name IN (N''Chậu Lan Hồ Điệp Trắng'', N''Chậu Lan Hồ Điệp Vàng'') AND p.name = N''Lan Hồ Điệp Sang Trọng'' AND (c.parent_id IS NULL OR c.parent_id <> p.id)'),
(N'UPDATE dbo.products SET category_id = (SELECT TOP 1 id FROM dbo.categories WHERE name = N''Bó Hoa Hồng Đỏ'') WHERE name LIKE N''%Hồng Đỏ%'' OR name LIKE N''%Ecuador%'''),
(N'UPDATE dbo.products SET category_id = (SELECT TOP 1 id FROM dbo.categories WHERE name = N''Bó Hoa Sinh Nhật'') WHERE name LIKE N''%Sinh Nhật%'' OR name LIKE N''%Bó Hoa%'''),
(N'UPDATE dbo.products SET category_id = (SELECT TOP 1 id FROM dbo.categories WHERE name = N''Kệ Hoa Khai Trương'') WHERE name LIKE N''%Khai Trương%'' OR name LIKE N''%Kệ Hoa%'''),
(N'UPDATE dbo.products SET category_id = (SELECT TOP 1 id FROM dbo.categories WHERE name = N''Chậu Lan Hồ Điệp Trắng'') WHERE name LIKE N''%Lan Hồ Điệp%'''),
(N'%Bạc%'),
(N'%Uy Tín%'),
(N'%Vàng%'),
(N'%Xuất Sắc%'),
(N'%Chuẩn%');
